p(d,'{{ПОГАШЕНО_АВАНСА}} — сумма, отнесённая на погашение по двусторонним актам; {{НЕПОГАШЕННЫЙ_ОСТАТОК}} — полученный аванс за вычетом этого погашения. {{РАСЧЁТНОЕ_САЛЬДО}} включает также неоплаченные работы и заявленные иные суммы. Оно не равно автоматически юридически подлежащей возврату сумме. {{ОТРАБОТАННАЯ_ЧАСТЬ}} не переносится из общей стоимости работ без анализа оплат и договорного порядка погашения.')
p(d,'{{АДРЕС_ЗАКАЗЧИКА}} и {{АДРЕС_ПОДРЯДЧИКА}} заполняются отдельно. Для карты 11 укажите источник срока ответа и возврата, доказательства события и статуса договора, статус каждой суммы, лист и строку расчёта, дату следующего действия. Незаполненные поля и невыбранные альтернативы в отправляемом документе недопустимы.')
d.save(O/'01-slovar-poley-avans.docx')

for f in O.glob('*.docx'):
 d=Document(f);norm(d)
 if f.name.startswith(('05','06','07')):
  title=next((x for x in d.paragraphs if 'ДОГОВОРУ' in x.text or 'ТРЕБОВАНИЕ О ВЫПЛАТЕ' in x.text),None)
  if title is not None:
   title.style='Title'
   for run in title.runs:run.font.size=Pt(13)
 for sec in d.sections:sec.top_margin=Twips(850);sec.bottom_margin=Twips(850)
 for s in d.styles:
  if s.type==1:
   s.font.name='Arial';s.font.color.rgb=RGBColor(0,0,0)
   s.font.size=Pt(10 if s.name=='Normal' else 16 if s.name=='Title' else 11)
   s.paragraph_format.space_after=Pt(6)
   if s._element.pPr is not None:
    for b in list(s._element.pPr.findall(qn('w:pBdr'))):s._element.pPr.remove(b)
   if s._element.rPr is not None:
    for c in s._element.rPr.findall(qn('w:color')):
     c.attrib.clear();c.set(qn('w:val'),'000000')
 for para in list(d.paragraphs)+[p for t in d.tables for row in t.rows for cell in row.cells for p in cell.paragraphs]:
  if para._p.pPr is not None:
   for b in list(para._p.pPr.findall(qn('w:pBdr'))):para._p.pPr.remove(b)
  for run in para.runs:
   run.font.color.rgb=RGBColor(0,0,0)
   if run._r.rPr is not None:
    for c in run._r.rPr.findall(qn('w:color')):c.attrib.clear();c.set(qn('w:val'),'000000')
 d.save(f)
print('Built',len(list(O.glob('*.docx'))),'DOCX')
